import os
import re
import shutil
import sqlite3
from pathlib import Path

from agents import function_tool

VAULT_ROOT = Path(os.environ.get("NOTES_VAULT", "~/notes")).expanduser()
INDEX_DB = VAULT_ROOT / ".index" / "vault.sqlite"


def _rewrite_notebook_field(text: str, notebook: str) -> str:
    match = re.match(r"^---\n(.*?)\n---\n", text, re.DOTALL)
    if not match:
        return f"---\nnotebook: {notebook}\n---\n{text}"
    header = match.group(1)
    if re.search(r"^notebook:", header, re.MULTILINE):
        header = re.sub(r"^notebook:.*$", f"notebook: {notebook}", header, flags=re.MULTILINE)
    else:
        header = f"{header}\nnotebook: {notebook}"
    return f"---\n{header}\n---\n" + text[match.end():]


@function_tool
def move_note_to_notebook(note_path: str, target_notebook: str) -> dict:
    source = (VAULT_ROOT / note_path).resolve()
    if not source.is_file() or VAULT_ROOT.resolve() not in source.parents:
        return {"ok": False, "error": f"Note not found: {note_path}"}

    dest_dir = (VAULT_ROOT / target_notebook).resolve()
    if VAULT_ROOT.resolve() not in dest_dir.parents and dest_dir != VAULT_ROOT.resolve():
        return {"ok": False, "error": "Target notebook must be inside the vault"}
    dest_dir.mkdir(parents=True, exist_ok=True)
    destination = dest_dir / source.name
    if destination.exists():
        return {"ok": False, "error": f"A note named {source.name} already exists in {target_notebook}"}

    updated = _rewrite_notebook_field(source.read_text(encoding="utf-8"), target_notebook)
    source.write_text(updated, encoding="utf-8")
    shutil.move(str(source), str(destination))

    old_rel = source.relative_to(VAULT_ROOT.resolve()).as_posix()
    new_rel = destination.relative_to(VAULT_ROOT.resolve()).as_posix()
    conn = sqlite3.connect(INDEX_DB)
    try:
        conn.execute(
            "UPDATE notes SET path = ?, notebook = ? WHERE path = ?",
            (new_rel, target_notebook, old_rel),
        )
        conn.execute("UPDATE links SET target_path = ? WHERE target_path = ?", (new_rel, old_rel))
        conn.commit()
    finally:
        conn.close()

    return {"ok": True, "old_path": old_rel, "new_path": new_rel}

import json
import subprocess
from pathlib import Path

LINT_BIN = "vault-lint"
SCAN_TIMEOUT = 300


def purge_orphaned_attachments(vault_dir: str, dry_run: bool = False) -> dict:
    vault = Path(vault_dir).expanduser().resolve()
    attachments_dir = vault / "attachments"
    if not attachments_dir.is_dir():
        return {"ok": False, "error": f"No attachments folder in {vault}"}

    cmd = [LINT_BIN, "orphans", "--vault", str(vault), "--kind", "attachments", "--format", "json"]
    with subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True) as proc:
        try:
            stdout, stderr = proc.communicate(timeout=SCAN_TIMEOUT)
        except subprocess.TimeoutExpired:
            proc.kill()
            return {"ok": False, "error": "vault-lint scan timed out"}
        if proc.returncode != 0:
            return {"ok": False, "error": stderr.strip() or f"vault-lint exited {proc.returncode}"}

    try:
        orphans = json.loads(stdout).get("orphans", [])
    except json.JSONDecodeError:
        return {"ok": False, "error": "Could not parse vault-lint output"}

    candidates = []
    for rel in orphans:
        path = (vault / rel).resolve()
        if attachments_dir in path.parents and path.is_file():
            candidates.append(path)

    if dry_run:
        return {
            "ok": True,
            "dry_run": True,
            "orphans": [p.relative_to(vault).as_posix() for p in candidates],
        }

    deleted, failed = [], []
    freed = 0
    for path in candidates:
        try:
            size = path.stat().st_size
            path.unlink()
            freed += size
            deleted.append(path.relative_to(vault).as_posix())
        except OSError as exc:
            failed.append({"path": path.relative_to(vault).as_posix(), "error": str(exc)})

    return {
        "ok": not failed,
        "dry_run": False,
        "deleted": deleted,
        "failed": failed,
        "bytes_freed": freed,
    }
